    ('54f03982-4f3e-42b5-a399-f5331833538c'::uuid, 3.0000::numeric, 2.0000000000000000::numeric),
    ('670a4628-00d7-467d-bfc7-11f73a155bb1'::uuid, 94.0000::numeric, 1.0189::numeric),
    ('5d7b5973-abab-4769-af06-78993d0a39b9'::uuid, 217.0000::numeric, 2.0000000000000000::numeric),
    ('f9fa0dbc-9fdc-49b0-8d43-58e5df1c8fbe'::uuid, 49.0000::numeric, 3500.0000000000000000::numeric),
    ('0a1bce2e-6fbd-4cc3-9f90-91c3cc90aae6'::uuid, 100.0000::numeric, 2.0000000000000000::numeric),
    ('53a5555e-9788-4cd8-a068-00f17a95ed60'::uuid, 200.0000::numeric, 280.0000000000000000::numeric),
    ('721b1217-1812-449d-9c92-bb89b080f7f6'::uuid, 20.0000::numeric, 2.0000000000000000::numeric)
    ) AS t(pid, q, w)
  LOOP
    SELECT stock_current, cost_average INTO v, v_w FROM products WHERE id = r.pid;
    IF v IS DISTINCT FROM r.q OR v_w IS DISTINCT FROM r.w THEN
      RAISE EXCEPTION 'ERR_UNIVERSE_DRIFT: % stock=%(exp %) wac=%(exp %)', r.pid, v, r.q, v_w, r.w;
    END IF;
  END LOOP;

  -- test residue intact (§5): 10 products, exact frozen stocks, zero ledger
  FOR r IN
    SELECT * FROM (VALUES
    ('5bf782be-70c8-4870-9514-46bc2ae9db69'::uuid, 15::numeric),
    ('530e198c-0d42-4b36-852e-ba86f4431d94'::uuid, 10::numeric),
