    ) AS t(pid, q, w)
  LOOP
    SELECT quantity INTO v FROM inventory WHERE product_id = r.pid AND store_id = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
    IF v IS DISTINCT FROM r.q THEN RAISE EXCEPTION 'ERR_INVARIANT_I4: inventory % = % (exp %)', r.pid, v, r.q; END IF;
    SELECT stock_current, cost_average INTO v, v_w FROM products WHERE id = r.pid;
    IF v IS DISTINCT FROM r.q THEN RAISE EXCEPTION 'ERR_INVARIANT_I3: stock_current % = % (exp %)', r.pid, v, r.q; END IF;
    IF v_w IS DISTINCT FROM r.w THEN RAISE EXCEPTION 'ERR_INVARIANT_I6: WAC % = % (exp %)', r.pid, v_w, r.w; END IF;
    SELECT COALESCE(SUM(quantity_change),0), count(*) INTO v, v_cnt
    FROM stock_movements WHERE product_id = r.pid AND store_id = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
    IF v <> r.q OR v_cnt <> 1 THEN RAISE EXCEPTION 'ERR_INVARIANT_I1: movements % Σ=% n=% (exp %,1)', r.pid, v, v_cnt, r.q; END IF;
    -- kardex 1:1 (I5): exactly one 'in' entry referencing the movement.
    -- NOTE: kardex_entries numeric columns are numeric(12,2) (canonical frozen
    -- typmod, evidence raw/r1_typmods.json) -> compare at the column's scale.
    -- The EXACT WAC/value lives in stock_movements.unit_cost (unbounded numeric)
    -- and products.cost_average (unbounded) — checked above.
    SELECT count(*) INTO v_cnt
    FROM kardex_entries k JOIN stock_movements m ON m.id = k.reference_id
    WHERE m.reference_doc = 'B10B-OBS2-RECON-OPENING:20260906T201637Z-S2HW' AND m.product_id = r.pid
      AND k.movement_type = 'in' AND k.quantity = round(r.q, 2)
      AND k.balance_quantity = round(r.q, 2) AND k.balance_unit_cost = round(r.w, 2)
      AND k.total_value = round(r.q * r.w, 2)
      AND k.reference_description = 'B10B-OBS2-RECON-OPENING:20260906T201637Z-S2HW';
    IF v_cnt <> 1 THEN RAISE EXCEPTION 'ERR_INVARIANT_I5: kardex % rows=% (exp 1)', r.pid, v_cnt; END IF;
    -- business_events (design I9): one 'initial' event with new_qty = q
    SELECT count(*) INTO v_cnt FROM business_events
    WHERE entity_id = r.pid AND payload->>'type' = 'initial'
      AND (payload->>'new_qty')::numeric = r.q AND payload->>'store_id' = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
    IF v_cnt <> 1 THEN RAISE EXCEPTION 'ERR_INVARIANT_BE: % events=% (exp 1)', r.pid, v_cnt; END IF;
  END LOOP;

  -- I14: no Test product included
  SELECT count(*) INTO v_cnt FROM stock_movements m
  WHERE m.reference_doc = 'B10B-OBS2-RECON-OPENING:20260906T201637Z-S2HW' AND m.product_id IN ('5bf782be-70c8-4870-9514-46bc2ae9db69'::uuid, '530e198c-0d42-4b36-852e-ba86f4431d94'::uuid, 'aa5e148b-df42-4349-a131-867767352669'::uuid, '94e53fd4-75ae-4924-a1b1-1b3d13f90df8'::uuid, '185f1c6f-e58a-4231-b39a-3a52f2c7ef22'::uuid, '7049d300-7e08-42f0-b081-d373a331d88c'::uuid, '7dbff68e-3ad1-479b-b228-f81021699ed4'::uuid, 'b7bd618c-38b4-475c-b775-dc81b233a825'::uuid, 'e9541bb4-97c2-4f1d-9cb2-836c38beefd7'::uuid, '8f4e2708-540c-477b-bef7-9aed96771a8f'::uuid);
  IF v_cnt <> 0 THEN RAISE EXCEPTION 'ERR_INVARIANT_I14: test products in batch (%)', v_cnt; END IF;

  -- I15: actor correct on every movement
  SELECT count(*) INTO v_cnt FROM stock_movements
  WHERE reference_doc = 'B10B-OBS2-RECON-OPENING:20260906T201637Z-S2HW' AND (created_by IS DISTINCT FROM '051c6157-600b-425e-b8c0-72388bacf541'::uuid);
  IF v_cnt <> 0 THEN RAISE EXCEPTION 'ERR_INVARIANT_I15: wrong created_by on % rows', v_cnt; END IF;

  -- I16: reference traceable end-to-end (movement -> kardex -> audit pending)
  SELECT count(*) INTO v_cnt FROM kardex_entries WHERE reference_description = 'B10B-OBS2-RECON-OPENING:20260906T201637Z-S2HW';
  IF v_cnt <> 98 THEN RAISE EXCEPTION 'ERR_INVARIANT_I16: kardex traceable rows=%', v_cnt; END IF;

  -- inventory shape: exactly 98 rows in store; others untouched (I11)
  SELECT count(*) INTO v_cnt FROM inventory WHERE store_id = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 98 THEN RAISE EXCEPTION 'ERR_INVARIANT_INVENTORY_STORE: % rows (exp 98)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM inventory WHERE store_id <> 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 141 THEN RAISE EXCEPTION 'ERR_INVARIANT_I11: other-store inventory % (exp 141)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM stock_movements WHERE store_id <> 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 702 THEN RAISE EXCEPTION 'ERR_INVARIANT_I11: other-store movements % (exp 702)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM kardex_entries WHERE store_id <> 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 702 THEN RAISE EXCEPTION 'ERR_INVARIANT_I11: other-store kardex % (exp 702)', v_cnt; END IF;

  -- §19 FINANCIAL NEUTRALITY (frozen PRE baselines)
  SELECT count(*) INTO v_cnt FROM transactions WHERE store_id = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 0 THEN RAISE EXCEPTION 'ERR_FINANCIAL_I7: store transactions %', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM transactions;
  IF v_cnt <> 520 THEN RAISE EXCEPTION 'ERR_FINANCIAL_I10: global transactions % (exp 520)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM transaction_items;
  IF v_cnt <> 555 THEN RAISE EXCEPTION 'ERR_FINANCIAL_I10: global transaction_items % (exp 555)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM payment_transactions;
  IF v_cnt <> 366 THEN RAISE EXCEPTION 'ERR_FINANCIAL_I8: global payments % (exp 366)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM commission_payments;
  IF v_cnt <> 0 THEN RAISE EXCEPTION 'ERR_FINANCIAL_I9: commissions % (exp 0)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM receipts WHERE store_id = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 0 THEN RAISE EXCEPTION 'ERR_FINANCIAL: store receipts % (exp 0)', v_cnt; END IF;
  SELECT count(*) INTO v_cnt FROM devolutions WHERE store_id = 'd1c4ba0e-5767-4ba0-e576-7d1c4ba0e576';
  IF v_cnt <> 13 THEN RAISE EXCEPTION 'ERR_FINANCIAL: store devolutions % (exp 13)', v_cnt; END IF;
END
